on conflict (pin_code) do update set
    area_name = excluded.area_name,
    district = excluded.district,
    state = excluded.state,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    coordinate_source = excluded.coordinate_source,
    updated_at = now();

-- These records identify source-verified oncology facilities; they are not ranked or endorsed as clinically best.
with seed (
    name, specialty, hospital_affiliation, address, city, state, postal_code,
    latitude, longitude, services, website_url, verification_source, last_verified_at,
    coordinate_source, ownership_type, address_verified
) as (values
    ('Tata Memorial Hospital', 'Cancer treatment and research', 'Tata Memorial Centre', 'Dr Ernest Borges Road, Parel', 'Mumbai', 'Maharashtra', '400012', 19.0049840, 72.8432125, array['medical_oncology','surgical_oncology','radiation_oncology'], 'https://tmc.gov.in/', 'https://tmc.gov.in/', date '2026-10-31', 'OpenStreetMap contributors, ODbL 1.0; hospital node 7052388277 (https://www.openstreetmap.org/node/7052388277)', 'government', true),
    ('ACTREC - Tata Memorial Centre', 'Cancer treatment, research and education', 'Tata Memorial Centre', 'Kharghar', 'Navi Mumbai', 'Maharashtra', '410210', 19.0465261, 73.0693562, array['medical_oncology','surgical_oncology','radiation_oncology'], 'https://actrec.gov.in/', 'https://actrec.gov.in/', date '2026-10-31', 'OpenStreetMap contributors, ODbL 1.0; PIN centroid (https://www.openstreetmap.org/)', 'government', true),
    ('HCG ICS Khubchandani Cancer Centre', 'Cancer care and oncology', 'HealthCare Global Enterprises', 'Maharishi Karve Road, opposite Cooperage Football Ground, Cooperage', 'Mumbai', 'Maharashtra', '400021', 18.9309900, 72.8285800, array['medical_oncology','surgical_oncology','radiation_oncology'], 'https://www.hcgoncology.com/', 'https://www.hcgoncology.com/cancer-centers/', date '2026-10-31', 'India Post office-coordinate mean for PIN 400021 (data.gov.in/node/6818285); approximate', 'private', true),
    ('HCG Cancer Hospital, Borivali', 'Cancer care and oncology', 'HealthCare Global Enterprises', 'Holy Cross Road, I C Colony, Borivali West', 'Mumbai', 'Maharashtra', '400092', 19.2291100, 72.8553100, array['medical_oncology','surgical_oncology','radiation_oncology'], 'https://www.hcgoncology.com/', 'https://www.hcgoncology.com/cancer-centers/', date '2026-10-31', 'India Post office-coordinate mean for PIN 400092 (data.gov.in/node/6818285); approximate', 'private', true)
)
insert into public.providers (
    name, specialty, hospital_affiliation, address, city, state, postal_code,
    latitude, longitude, services, website_url, verification_source, last_verified_at,
    verified, ownership_type, address_verified, coordinate_source
)
select
    seed.name, seed.specialty, seed.hospital_affiliation, seed.address, seed.city, seed.state, seed.postal_code,
    seed.latitude, seed.longitude, seed.services, seed.website_url, seed.verification_source, seed.last_verified_at,
    true, seed.ownership_type, seed.address_verified, seed.coordinate_source
from seed
where not exists (
    select 1 from public.providers existing
    where lower(existing.name) = lower(seed.name)
      and existing.postal_code = seed.postal_code
);

notify pgrst, 'reload schema';
